assert len(SERVICES_DEF) > 200, f'Too few services, got {len(SERVICES_DEF)}'

def build_svc(slug, defn):
    display, parent, price, mesh, material, tmpl_key, hero_sfx = defn
    T = SVC_TEMPLATES[tmpl_key]
    hero = f'{display} in %s, Hyderabad — {hero_sfx}'
    p1 = T['p1_tmpl'].format(dn=display, mesh=mesh, material=material, price=price)
    p2 = T['p2_tmpl'].format(dn=display, mesh=mesh, material=material, price=price)
    faqs = [[q.format(dn=display, mesh=mesh, material=material, price=price), a.format(dn=display, mesh=mesh, material=material, price=price)] for q, a in T['faqs_tmpl']]
    specs = [['Material', material], ['Mesh/Type', mesh], ['Starting Price', price], ['UV Life', '7-10 Years'], ['Warranty', '5 Years'], ['Dealer', 'Authorized Russea']]
    return {'display': display, 'parent': parent, 'price': price, 'specs': specs, 'hero': hero, 'p1': p1, 'p2': p2, 'faqs': faqs}

# ---- WRITE _data.php ----
lines = ['<?php', '/* GCM Enterprises — Shared data: areas + services for nets.php and n.php */', '$areas=[']
for slug, (label, zone, near) in AREAS.items():
    nl = ','.join(f"'{n}'" for n in near)
    lines.append(f"'{slug}'=>['label'=>'{label}','zone'=>'{zone}','near'=>[{nl}]],")
lines.append('];')
lines.append('$svc_data=[')
for slug, defn in SERVICES_DEF.items():
    s = build_svc(slug, defn)
    specs_php = ','.join(f"['{r[0]}','{r[1]}']" for r in s['specs'])
    faqs_php = ','.join(f"['{q.replace(chr(39), chr(39))}','{a.replace(chr(39), chr(39))}']" for q, a in s['faqs'])
    p1_esc = s['p1'].replace("'", "\\'")
    p2_esc = s['p2'].replace("'", "\\'")
    hero_esc = s['hero'].replace("'", "\\'")
    lines.append(f"'{slug}'=>['display'=>'{s['display']}','parent'=>'{s['parent']}','price'=>'{s['price']}',"
                 f"'specs'=>[{specs_php}],"
                 f"'hero'=>'{hero_esc}',"
                 f"'p1'=>'{p1_esc}',"
                 f"'p2'=>'{p2_esc}',"
                 f"'faqs'=>[{faqs_php}]],")
lines.append('];')

data_php = '\n'.join(lines)
with open(os.path.join(BASE, '_data.php'), 'w', encoding='utf-8') as f:
    f.write(data_php)
print(f'_data.php written: {len(lines)} lines')
print(f'Areas: {len(AREAS)}, Services: {len(SERVICES_DEF)}')
print(f'Base pages (nets.php): {len(AREAS) * len(SERVICES_DEF)}')
print(f'Variant pages (n.php 8 intents): {len(AREAS) * len(SERVICES_DEF) * 8}')
print(f'Total dynamic: {len(AREAS) * len(SERVICES_DEF) * 9}')
